entries[229193] = { ["name"] = "Queen's Pheromone", ["text"] = "Binds when picked up\nUse: The pheromones of the Queen.\n\nGuards in the City of Threads will no longer interfere with you.\n\"The pheromones of the Queen. Obtained discreetly. Guards in the City of Threads will no longer be able to detect you.\"" }
