entries[229196] = { ["name"] = "Bakar Sketch", ["text"] = "Secrets of Azeroth\nQuest Item\n\"Some aspiring artist must have drawn this and left it here. The drawing resembles a small bakar.\"\nSell Price:" }
entries[229198] = { ["name"] = "Ace of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a hand emerging from a cloud, gripping a sword encircled by a crown.\"" }
entries[229199] = { ["name"] = "Two of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a blindfolded figure balancing two strong winds upon their shoulders.\"" }
entries[229200] = { ["name"] = "Three of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts three jets of stormy wind piercing a heart, with tumultuous clouds and rain behind.\"" }
entries[229201] = { ["name"] = "Four of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts the effigy of a knight in the attitude of prayer, at full length upon, presumably, their tomb.\"" }
entries[229202] = { ["name"] = "Five of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a disdainful man scowling at two retreating and dejected figures who've left their sacks of air lying upon the ground. He carries two others on his left shoulder, and a third is in his right hand.\"" }
entries[229203] = { ["name"] = "Six of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a ferrier carrying passengers in their boat to the farther shore. The course is smooth, and seeing that the freight is light, it may be noted that the work is not beyond their strength.\"" }
entries[229204] = { ["name"] = "Seven of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a person in the act of carrying five winds away rapidly. Two other winds rest on the ground, and a camp is close by.\"" }
entries[229205] = { ["name"] = "Eight of Air", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a bound and blindfolded captive, surrounded by eight tumultuous winds. Yet, it is of temporary restraint rather than of irrevocable bondage.\"" }
entries[229206] = { ["name"] = "Ace of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a hand emerging from a burning ball of fire, grasping a wand encircled by smoke.\"" }
entries[229207] = { ["name"] = "Two of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a tall figure looking out from a battlement roof over the sea and shore. They hold a globe in their right hand and a burning staff in their left, resting it on the battlement. Another burning staff is fixed in a ring to the figure's right.\"" }
entries[229208] = { ["name"] = "Three of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a calm, stately figure with their back turned, looking from a cliff's edge at ships passing over the sea beyond. Three staves are planted in the ground, each holding a lantern, and the figure leans slightly on one of them.\"" }
entries[229209] = { ["name"] = "Four of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts four large pillars in the foreground, with a grand garland of the purest flame suspended between them. Two figures hold up fragrant flowers, and at their side is a bridge over a moat leading to an old manor.\"" }
entries[229210] = { ["name"] = "Five of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a posse of five youths brandishing staves as if in sport. It is mimic warfare, and their eyes burn with fire.\"" }
entries[229211] = { ["name"] = "Six of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a figure on horseback adorned with a laurel crown and wielding a flaming sword. Five footmen with similar flaming swords are at the figure's side.\"" }
entries[229212] = { ["name"] = "Seven of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a determined figure standing on a rugged hill, holding a torch high above. Six other torches are being raised towards them from below.\"" }
entries[229213] = { ["name"] = "Eight of Fire", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a flight of eight flaming arrows streaking the heavens as they draw to the end of their course. What they signify is at hand--it may even be on the threshold.\"" }
entries[229214] = { ["name"] = "Ace of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a hand emerging from lands covered in freshly fallen snow, clasping the stem of a goblet filled to overflowing with steaming water.\"" }
entries[229215] = { ["name"] = "Two of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts two youths standing in a winter scene, toasting each other with flagons made of the purest ice.\"" }
entries[229216] = { ["name"] = "Three of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts revelers dancing in a garden with cups uplifted as if pledging to one another. Soft snow falls around them.\"" }
entries[229217] = { ["name"] = "Four of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a figure draped in furs, sitting under a pine tree, contemplating three chalices resting in the snow before them. An arm issuing from a cloud offers the figure a fourth chalice. Their expression betrays discontentment.\"" }
entries[229218] = { ["name"] = "Five of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a dark, cloaked figure looking sideways at three prone cups resting in pools of water. Two other cups stand upright behind the figure on pedestals of ice. In the background, a bridge leads to a small keep.\"" }
entries[229219] = { ["name"] = "Six of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts children in an old garden, watering flowers with cups full of melting snow.\"" }
entries[229220] = { ["name"] = "Seven of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts strange visions pouring from seven chalices made of the purest ice. But these images are those of a fantastic spirit.\"" }
entries[229221] = { ["name"] = "Eight of Frost", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a figure of a dejected aspect walking away, leaving behind the cups of its fortune, enterprise, undertaking, or previous concern to be engulfed by the encroaching ice.\"" }
entries[229222] = { ["name"] = "Ace of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a hand emerging from the rocky ground in a cloud of dust holding up a stone disk.\"" }
entries[229223] = { ["name"] = "Two of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a child in the act of dancing with a stone disk in either hand. The disks are joined by that endless cord, which is like the number 8 reversed.\"" }
entries[229224] = { ["name"] = "Three of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a sculptor at work in a monastery. The apprentice has received their reward and is now at work in earnest.\"" }
entries[229225] = { ["name"] = "Four of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a crowned figure with a stone disk over its head, clasping another disk with hands and arms and two more disks under its feet. They hold to that which they have.\"" }
entries[229226] = { ["name"] = "Five of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts two beggars in a dust storm as they pass a window lighted by five glowing stone disks.\"" }
entries[229227] = { ["name"] = "Six of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts a person in the guise of a merchant weighing money on a pair of scales and distributing it to the needy and distressed. It is a testimony to their own success in life, as well as to their goodness of heart.\"" }
entries[229228] = { ["name"] = "Seven of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts an adolescent, leaning on their staff, looking intently at seven stone disks attached to a clump of greenery on their right. One might say these were treasures and that the young one's heart was there.\"" }
entries[229229] = { ["name"] = "Eight of Earth", ["text"] = "Darkmoon Fortune Deck\n\"This depicts an artist in stone at work, which they exhibit in the form of trophies.\"" }
