entries[229348] = { ["name"] = "Keys to Incognitro, the Indecipherable Felcycle", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Incognitro, the Indecipherable Felcycle.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This demonic machine was designed by Chief Engineer Ulzik as an experiment in cross-dimensional traversal. Despite many deaths during testing, Ulzik remained confident that this vehicle would reveal secrets of the universe previously unknowable.\"\nWorld Event:\nWoW's 20th Anniversary?" }
entries[229350] = { ["name"] = "Chew Toy", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique" }
entries[229351] = { ["name"] = "Spiritual Incense", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUse: Conjures a spiritual link to Maru the Junior Sleuth. Maru can provide hints for some Secrets of Azeroth.\n\"A bowl of aromatic ambergris blessed to honor Oacha'noa.\"\nSell Price:" }
entries[229353] = { ["name"] = "Rage-Filled Idol", ["text"] = "Binds when picked up" }
entries[229354] = { ["name"] = "Algari Adventurer's Cache", ["text"] = "Binds when picked up\n\"Weekly cache containing leveling gear, gold, and more.\"\n<Right Click to Open>" }
entries[229355] = { ["name"] = "Chromie's Premium Goodie Bag", ["text"] = "Binds when picked up\n\"Contains gold, valorstones, a chance for crests, and a Warbound Until Equipped item.\"\n<Right Click to Open>" }
entries[229358] = { ["name"] = "Miniature Tuskarr Boat", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"This must belong to Maru.\"" }
entries[229359] = { ["name"] = "Chromie's Goodie Bag", ["text"] = "Binds when picked up\n\"Contains a Warbound Until Equipped item appropriate for your level and class.\"\n<Right Click to Open>" }
entries[229361] = { ["name"] = "Xal'atath, Blade of the Black Empire", ["text"] = "Quest Item\nUnique\n\"Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.\"" }
entries[229363] = { ["name"] = "Zaranit Bud", ["text"] = "Quest Item\n\"A zaranit flower bud from a plant carefully grown within the intact eco-dome on K'aresh.\"" }
entries[229364] = { ["name"] = "Scourge Crest", ["text"] = "Cosmetic\nBinds to Warband\nBack\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[229365] = { ["name"] = "Raw Singing Citrine", ["text"] = "Binds when picked up\nUse: Imbue Cyrce's Circlet with the raw magic of this citrine, increasing its item level.\n\"You hear an alluring song while this sits idly in your inventory. Bashfully, the song retreats into a hushed voice when held to your ear.\"\nSell Price:" }
entries[229366] = { ["name"] = "Brrrgl", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss Brrrgl.\nRequires level 1 to 80 ( 80)" }
entries[229367] = { ["name"] = "Ghostly Celebration Crate", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique\nThis Item Begins a Quest" }
entries[229368] = { ["name"] = "Gill'el", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRequires level 1 to 80 ( 80)" }
entries[229369] = { ["name"] = "Ghostly Ransom Note", ["text"] = "Secrets of Azeroth\nBinds when picked up\n<Right Click to Read>" }
entries[229370] = { ["name"] = "Companion Experience" }
entries[229371] = { ["name"] = "Companion Experience" }
entries[229375] = { ["name"] = "Neural Enlarger", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique\nUse: Temporarily enhance your sleuthing tools, significantly increasing the visibility of the Idol of Ohn'ahra and Tricked-Out Thinking Cap.\nSell Price:" }
entries[229383] = { ["name"] = "Play Script", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique" }
entries[229384] = { ["name"] = "Prop Sword", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique" }
entries[229385] = { ["name"] = "Mask of the Trickster", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique" }
entries[229386] = { ["name"] = "Conductor's Baton", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUnique" }
entries[229387] = { ["name"] = "Trickster's Riddles", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n<Right Click to Read>" }
entries[229388] = { ["name"] = "Prized Combatant's Heraldry", ["text"] = "The War Within Season 2\nOptional Crafting Reagent\n\n\"Acquired from various PvP activities or purchased with Honor from PvP quartermasters in Dornogal. Can be bought and sold on the Auction House.\"" }
entries[229389] = { ["name"] = "Prized Aspirant's Heraldry", ["text"] = "The War Within Season 2\nBinds when picked up\nOptional Crafting Reagent\n+50 Recipe Difficulty\n\"Purchased with Honor from PvP quartermasters in Dornogal.\"" }
entries[229390] = { ["name"] = "Prized Gladiator's Heraldry", ["text"] = "The War Within Season 2\nBinds when picked up\nOptional Crafting Reagent\n+150 Recipe Difficulty\n\"Purchased with Conquest from PvP quartermasters in Dornogal.\"" }
entries[229392] = { ["name"] = "Crumpled Delivery Note", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"A letter written to the Underrider Gang detailing payments in the form of weapons.\"" }
entries[229393] = { ["name"] = "Lapbug Essence", ["text"] = "Quest Item\n\"You can see a cloudy substance moving in this jar. It occasionally shoots forward into the jar's edge and dissipates.\"" }
entries[229395] = { ["name"] = "Slateback Essence", ["text"] = "Quest Item\n\"The mist in this jar sits heavily on the bottom. Swirling the jar around shows it's acting more like liquid than a gas.\"" }
entries[229396] = { ["name"] = "Flyer Essence", ["text"] = "Quest Item\n\"The particles in this jar are constantly moving around. You can make out small twinkles, almost star-like in the depths of its murk.\"" }
entries[229401] = { ["name"] = "Artisan's Consortium Pamphlet", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A special notice for eager competitors of all ranks!\"" }
entries[229405] = { ["name"] = "Entropic Core", ["text"] = "Quest Item\n\"Condensed energies siphoned from the soil of K'aresh.\"" }
entries[229407] = { ["name"] = "Citrus Acid", ["text"] = "Quest Item\n\"Whether this will improve the taste of grog is up for debate.\"" }
entries[229408] = { ["name"] = "Burnt Feather", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The feather looks battle-worn, burnt, torn in areas, and a strange green liquid is dripping off the end of it.\"" }
entries[229409] = { ["name"] = "Plucked Feather", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The feather appears to have been purposely plucked and altered to be missing exactly 48 barbs on the left and has a remaining 93 barbs on the right.\"" }
entries[229410] = { ["name"] = "Frozen Feather", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The feather is frozen and has a strange combination of scents: volcanic ash, saltwater, and engine oil.\"" }
entries[229411] = { ["name"] = "Normal Feather", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The feather appears unaltered as expected at the start of a journey.\"" }
entries[229412] = { ["name"] = "Devourer Anima", ["text"] = "Quest Item\n\"Plucked from the corpse of a devourer, this anima swirls languidly and glows with a bright blue light.\"" }
entries[229413] = { ["name"] = "\"Dogg-Saron\" Costume", ["text"] = "Use: Dress up your Perky Pug.\n\"A re-labeled knockoff of an old Hallow's End costume.\"\nSell Price:" }
entries[229414] = { ["name"] = "Moira Thaurissan's Hammer", ["text"] = "Binds when equipped\nOne-Hand Mace\n1 Damage Speed 2.60\n(0.4 damage per second)\nSell Price:" }
entries[229418] = { ["name"] = "Reins of the Trader's Gilded Brutosaur", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this three-person mount with vendors.\nSummons and dismisses your Trader's Gilded Brutosaur.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Morten and Killia never realized how much their new trading partnership across faction lines would pay off. That is until the day they were able to purchase this fine creature to aid them in their travels. And of course do it in gilded style.\"\nIn-Game Shop" }
entries[229419] = { ["name"] = "Barrelbottom Deed", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"The deed to Barrelbottom Apartments. Moz won't be needing this anymore.\"" }
entries[229420] = { ["name"] = "Anima Orb", ["text"] = "Quest Item\nUse: Throw a ball to your friendly animal.\n\"A tactile ball of anima. It squeaks when you throw it. Animals seem to love it.\"" }
entries[229422] = { ["name"] = "Undermine Equipment Chest", ["text"] = "The War Within Season 2\nBinds to Warband\nUse: Create a soulbound dungeon item appropriate for your loot specialization during The War Within Season 2." }
