entries[229780] = { ["name"] = "Prized Gladiator's Badge of Ferocity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,086 Critical Strike\nUse: Increases primary stat by 5716 for 15 sec. (1 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[229781] = { ["name"] = "Prized Gladiator's Insignia of Alacrity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,086 Haste\nEquip: Your spells and abilities have a chance to grant 4824 primary stat for 20 sec.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[229782] = { ["name"] = "Prized Gladiator's Emblem", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+2,161 [Agility or Strength or Intellect]\nUse: Increases maximum health by 1068896 for 15 sec. (2 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[229783] = { ["name"] = "Prized Gladiator's Medallion", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+2,161 [Agility or Strength or Intellect]\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[229784] = { ["name"] = "Prized Gladiator's Sigil of Adaptation", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+2,161 [Agility or Strength or Intellect]\nEquip: Removes any loss of control effect with a duration of 5 seconds or more. This effect can only occur once every 1 min.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
