entries[229892] = { ["name"] = "Void Glass Sample", ["text"] = "Quest Item\n\"Shards of void-infused glass from the surface of K'aresh.\"" }
entries[229893] = { ["name"] = "Ways of the Priesthood", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"This old and tattered prayer book has seen better days. A closer look at its pages reveals that the priests use a type of cuneiform for writing. It doesn't make much sense to you.\"" }
entries[229895] = { ["name"] = "Scepter of Priesthood", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"This scepter belongs to the K'areshi high priests. Ethereal energy runes come to life when you pick it up, and hum faintly before vanishing.\"" }
entries[229898] = { ["name"] = "Capture Device", ["text"] = "Quest Item\nUnique\nUse: Use to capture incapacitated escaped creatures within Tazavesh. (2 Sec Cooldown)" }
entries[229899] = { ["name"] = "Coffer Key Shard", ["text"] = "The War Within Season 1\nBinds when picked up\n\"Acquired from treasures, Radiant Echos, World Quests, and outdoor events throughout Khaz Algar.\"\nSell Price:" }
entries[229900] = { ["name"] = "Softly Swirling Mote", ["text"] = "Quest Item\n\"This small orb of swirling energy pulses in time with your heartbeat.\"" }
entries[229901] = { ["name"] = "Krolusk Husk", ["text"] = "Quest Item\n\"The brittle shell of a K'areshi Krolusk.\"" }
entries[229902] = { ["name"] = "K'areshi Priest's Bowl", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"A ceremonial bowl used by the K'areshi Priesthood. It was used for rituals and eating alike, at least until the ethereals stopped doing both.\"" }
entries[229905] = { ["name"] = "Satchel of Seeds", ["text"] = "Quest Item\n\"A satchel of packets, which each bear seeds of various shapes and sizes. Alongside the packets is a neatly folded, handwritten note detailing care and planting instructions.\"" }
entries[229908] = { ["name"] = "Plush Toy", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique" }
entries[229913] = { ["name"] = "Letter from Aysa", ["text"] = "Quest Item\nUnique\n\"A handwritten letter from Aysa.\"\n<Right Click to Read>" }
entries[229924] = { ["name"] = "Darkfuse Chompactor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Gallagio Loyalty Rewards Club.\n\n\"Considered the Top Dog among Stix's Junkyard Hyenas, it boasts a bite force strong enough to crush whatever - or whoever - Gallywix wants disposed of.\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:" }
entries[229935] = { ["name"] = "Crimson Armored Growler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted reputation with the Bilgewater Cartel in Undermine.\n\n\"Some Goblins affectionately refer to trained hyenas as 'Growlers.' This one is fond of digging.\"\nVendor:\nRocco Razzboom\nZone:\nUndermine\nCost:\n8125" }
entries[229936] = { ["name"] = "Violet Armored Growler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 15 with the Cartels of Undermine.\n\n\"Smaks knows a thing or two about caring for hyenas. Rule number one: keep your hands away from those teeth!\"\nVendor:\nSmaks Topskimmer\nZone:\nUndermine\nCost:\n8125" }
entries[229937] = { ["name"] = "Blackwater Bonecrusher", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Best keep those bones to yourself if you don't want them crushed.\"\nDrop:\nBlackwater Trove\nZone:\nUndermine" }
entries[229940] = { ["name"] = "Flarendo the Furious", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 20 with the Gallagio Loyalty Rewards Club.\n\n\"Being the VIP of VIPs at the Gallagio has its perks, including the keys to this former King of Carnage. Cutting-edge goblin technology allows him to achieve over 100 yards per gallon!\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:" }
entries[229941] = { ["name"] = "Innovation Investigator", ["text"] = "Binds when used\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When the best path to a good idea is going really fast.\"\nVendor:\nSkedgit Cinderbangs\nZone:\nUndermine\nCost:\n25" }
entries[229943] = { ["name"] = "Steamwheedle Supplier", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Supplies you with a quick trip, or your enemies with a large explosion!\"\nDrop:\nSteamwheedle Trove\nZone:\nUndermine" }
entries[229944] = { ["name"] = "The Topskimmer Special", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 19 with the Cartels of Undermine.\n\n\"Smaks is sure this rocket won't explode mid-flight. Absolutely. Positively. 100%. Sure.\"\nVendor:\nSmaks Topskimmer\nZone:\nUndermine\nCost:\n11375" }
entries[229945] = { ["name"] = "Thunderdrum Misfire", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 8 with the Gallagio Loyalty Rewards Club.\n\n\"Recovered from the Cauldron's bleachers during a particularly gruesome clash. When asked if it was a dud, Torq's operator simply replied: 'Probably?'\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:" }
entries[229946] = { ["name"] = "Ochre Delivery Rocket", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted reputation with the Venture Company Cartel in Undermine.\n\n\"Get packages and passengers from point A to B in style!\"\nVendor:\nShredz the Scrapper\nZone:\nUndermine\nCost:\n11375" }
entries[229947] = { ["name"] = "Violet Goblin Shredder", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This shredder has been lovingly painted with a non-corrosive paint to ensure a lasting sheen.\"\nDrop:\nShipping and Handling\nZone:\nUndermine" }
entries[229948] = { ["name"] = "Blackwater Shredder Deluxe Mk 2", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted reputation with the Blackwater Cartel in Undermine.\n\n\"Best not to ask what happened to Mk 1.\"\nVendor:\nBoatswain HardeeZone:\nUndermineCost:\n8125" }
entries[229949] = { ["name"] = "Personalized Goblin S.C.R.A.P.per", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Goblin Shredders have proven time and again to be useful in many applications, such as in logging and transportation. This model has been repurposed for use by S.C.R.A.P..\"\nDrop:\nSifted Pile of Scrap\nZone:\nUndermine" }
entries[229950] = { ["name"] = "Darkfuse Demolisher", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Revered reputation with the Darkfuse Cartel in Undermine.\n\n\"Excellent at making a mess of things. Not so great at cleaning them up.\"\nVendor:\nSitch Lowdown\nZone:\nUndermine\nCost:\n11375" }
entries[229951] = { ["name"] = "Venture Co-ordinator", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Built to manage any Venture-related operation from the front lines.\"\nDrop:\nVenture Co. Trove\nZone:\nUndermine" }
entries[229952] = { ["name"] = "Asset Advocator", ["text"] = "Binds when used\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Assuring others that your assets are exactly where they should be.\"\nVendor:\nSkedgit CinderbangsZone:\nUndermineCost:\n25" }
entries[229953] = { ["name"] = "Salvaged Goblin Gazillionaire's Flying Machine", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Once the prized possession of elite goblin society, this flying machine was sadly relegated to the scrap heap after something bigger, brighter, and more explosive arrived on the market.\"\nDrop:\nGallagio Garbage\nZone:\nUndermine" }
entries[229954] = { ["name"] = "Margin Manipulator", ["text"] = "Binds when used\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Ensuring there is always some marginal distance between you and rock bottom.\"\nVendor:\nSkedgit Cinderbangs\nZone:\nUndermine\nCost:\n25" }
entries[229955] = { ["name"] = "Darkfuse Spy-Eye", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Perfect for the up-and-comer who wants to climb the ladder by making everyone else's business THEIR business.\"\nWorld Quest:\nDarkfuse Precipitant\nZone:\nUndermine" }
entries[229956] = { ["name"] = "Mean Green Flying Machine", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted reputation with the Steamwheedle Cartel in Undermine\n\n\"Steamwheedle's top engineers claim they invented this work of mechanical genius, while the other cartels copied their plans.\"\nVendor:\nLab Assistant Laszly\nZone:\nUndermine\nCost:\n11375" }
entries[229957] = { ["name"] = "Bilgewater Bombardier", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"For rapid transport of Cartel trade goods and other highly volatile substances.\"\nDrop:\nBilgewater Trove\nZone:\nUndermine" }
entries[229958] = { ["name"] = "Decorated Feather", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"The feather has been decorated with ancient Arakkoa beading. It appears to have fallen from a great height as some of the beads have shattered.\"" }
entries[229959] = { ["name"] = "Void-Infused Shard", ["text"] = "Quest Item\n\"A shard of violet glass, infused with void energy.\"" }
entries[229960] = { ["name"] = "Cheerbringer XL", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Mace\n1 Damage Speed 3.60\n(0.3 damage per second)\n\"You WILL be cheerful - or else!\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[229961] = { ["name"] = "Candied Knife", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Dagger\n1 Damage Speed 1.80\n(0.6 damage per second)\n\"The more you lick it, the sharper it gets.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[229962] = { ["name"] = "Tree Topper", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Staff\n1 Damage Speed 3.60\n(0.3 damage per second)\n\"If a tree impales someone in the woods and nobody is around... at least they heard it.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[229963] = { ["name"] = "Great Candied Blade", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 Damage Speed 3.60\n(0.3 damage per second)\n\"Guaranteed to cut tongues and enemies!\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[229967] = { ["name"] = "Salvageable Scrap", ["text"] = "Quest Item" }
entries[229968] = { ["name"] = "Boonful Banquet", ["text"] = "Secrets of Azeroth\nQuest Item\nUnique\n\"This handwritten note looks like a list of instructions, but none of it makes any sense. Maybe someone in Booty Bay can help decipher this.\"\n<Right Click to Read>" }
entries[229969] = { ["name"] = "Flickering Essence", ["text"] = "Quest Item\n\"The mote of pure energy flickers at a set tempo with two beats. Ba-bump, ba-bump, ba-bump.\"" }
entries[229970] = { ["name"] = "Blood of K'aresh Deposit", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"These blue and transparent crystals can be found in small colonies. They are smooth with an oily film on them that seems to repel sand.\"" }
entries[229974] = { ["name"] = "Delver's Gob-Trotter", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Delver's Gob-Trotter.\n\nThis mount can use Ride Along.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This aircraft will help you delve straight into adventure, if it doesn't explode!\"\nWorld Quest:\nI Want My Hat Back\nZone:\nIsle of Dorn\nZone:\nDornogal" }
entries[229987] = { ["name"] = "Prized Gladiator's Fel Bat", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Awakened from caves in the battlefield, and armored to the fray.\"\nAchievement:\nGladiator: The War Within Season 2\nCategory:\nPlayer vs. Player" }
entries[229988] = { ["name"] = "Vicious Electro Eel", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These aquatic beasts enjoy torturing the Alliance with their electric shocks.\"\nPvP:\nThe War Within: Season 2\nRated Arena and Rated Battleground Season Reward" }
entries[229989] = { ["name"] = "Vicious Electro Eel", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These aquatic beasts enjoy torturing the Horde with their electric shocks.\"\nPvP:\nThe War Within: Season 2\nRated Arena and Rated Battleground Season Reward" }
