entries[229999] = { ["name"] = "Classic Cloudy Tabard", ["text"] = "Cosmetic\nBinds to Warband\nTabard\n\"A simple tabard for many occasions.\"\nUse: Add this appearance to your Warband collection." }
entries[230000] = { ["name"] = "Ellie", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"A well-loved elekk plush with the name Ellie written on it. The seams have begun to wear and its button eyes are loose.\"" }
entries[230011] = { ["name"] = "Lil'Kaz's Hilt", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRight-click to summon and dismiss Lil'Doomy.\nRequires level 1 to 80 ( 80)" }
entries[230017] = { ["name"] = "Master Blaster's Insignia", ["text"] = "The War Within Season 2\nBinds when picked up\nUnique\n\"Awarded for outstanding service to the denizens of the Undermine. Bring it to Teddo Bridgeblaster or Giggi Clobbersocket in the Incontinental Hotel to receive powerful equipment for your efforts.\"" }
entries[230019] = { ["name"] = "Vexie's Pit Whistle", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\nUse: Summon Pitbot Geardo to assist you for 5 sec, coating nearby enemies with rancid motor oil for additional threat. Geardo ensures you take the blame.\n\nGeardo departs explosively to deal 699165 Fire damage split between nearby enemies, increased by 15% if recently oiled. (500ms cooldown) (1 Min, 30 Sec Cooldown)\nDefeat Vexie in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230026] = { ["name"] = "Scrapfield 9001", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\nEquip: Falling below 60% health surrounds you with a protective vortex of junk, reducing damage taken by 50% for 15 sec or until 996802 damage is prevented. This effect may only occur every 30 sec.\n\nAfter 20 sec without activating while in combat, the Scrapfield overloads to energize you with 2651 Haste for 12 sec.\nValid only for tank specializations.\nDefeat Stix Bunkjunker in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[230027] = { ["name"] = "House of Cards", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\nUse: Deal yourself in, granting you [source value] to [source value] Mastery for 15 sec and stacking the deck. Stacking the deck increases the minimum Mastery on future hands by [source value] until you leave combat, up to 3 times. (1 Min, 30 Sec Cooldown)\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\nSell Price:", ["unresolvedValues"] = true }
entries[230029] = { ["name"] = "Chromebustible Bomb Suit", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,341 Haste\nUse: Rapidly deploy the bomb suit to reduce damage taken by 75% for 20 sec or until 6290790 damage has been prevented.\n\nUpon depletion, the bomb suit detonates to deal 529552 Fire damage split between nearby enemies. (1 Min, 30 Sec Cooldown)\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\n\"When the only options are initial success or total failure.\"\nSell Price:" }
entries[230030] = { ["name"] = "Cartel Ve Communicator", ["text"] = "Quest Item\n\"This appears to be some form of worked Stygia. You can feel it pulsating slowly in your hand.\"" }
entries[230032] = { ["name"] = "Overflowing K'aresh Trust Trove", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves true allies of the K'aresh Trust.\"\n<Right Click to Open>" }
